update public.f_star set 
  class = (select pg_catalog.min(class) from public.f_star)
    , 
  aa = (select unique1 from public.tenk1 limit 1 offset 98)
    , 
  ff = public.f_star.ff, 
  f = cast(nullif(case when public.f_star.ff >> public.f_star.ff then public.f_star.e else public.f_star.e end
      ,
    public.f_star.aa) as int4)
returning 
  public.f_star.cc as c0, 
  public.f_star.e as c1, 
  public.f_star.f as c2, 
  public.f_star.cc as c3, 
  public.f_star.aa as c4, 
  (select four from public.onek limit 1 offset 2)
     as c5

